package ie

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func TestPDUAddrUnmarshalBinary(t *testing.T) {
	t.Parallel()

	testCases := []struct {
		name     string
		input    []byte
		expected *PDUAddr
	}{
		{
			name:  "Positive Case - V4",
			input: []byte{0x01, 0x12, 0x34, 0x56, 0x78},
			expected: &PDUAddr{
				IPv4: []byte{0x12, 0x34, 0x56, 0x78},
			},
		},
		{
			name: "Positive Case - V6",
			input: []byte{
				0x02, 0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			expected: &PDUAddr{
				IPv6IfId: []byte{
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name: "Positive Case - V4V6",
			input: []byte{
				0x03,
				0x12, 0x34, 0x56, 0x78, 0x78, 0x56, 0x34, 0x12,
				0xaa, 0xbb, 0xcc, 0xdd,
			},
			expected: &PDUAddr{
				IPv6IfId: []byte{
					0x12, 0x34, 0x56, 0x78, 0x78, 0x56, 0x34, 0x12,
				},
				IPv4: []byte{0xaa, 0xbb, 0xcc, 0xdd},
			},
		},
		{
			name: "Positive Case - V4 + si6lla",
			input: []byte{
				0x09,
				0x12, 0x34, 0x56, 0x78,
				0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
				0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			expected: &PDUAddr{
				IPv4: []byte{0x12, 0x34, 0x56, 0x78},
				SMFIPv6LLA: []byte{
					0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name: "Positive Case - V6 + si6lla",
			input: []byte{
				0x0a,
				0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
				0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			expected: &PDUAddr{
				IPv6IfId: []byte{
					0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				},
				SMFIPv6LLA: []byte{
					0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name: "Positive Case - v4V6 + si6lla",
			input: []byte{
				0x0b,
				0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				0xde, 0xad, 0xbe, 0xef,
				0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
				0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			expected: &PDUAddr{
				IPv6IfId: []byte{
					0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				},
				IPv4: []byte{0xde, 0xad, 0xbe, 0xef},
				SMFIPv6LLA: []byte{
					0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name:  "Negative Case bad length",
			input: []byte{0x76, 0x54},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			ie := new(PDUAddr)
			err := ie.UnmarshalBinary(tc.input)
			if tc.expected != nil {
				require.NoError(t, err)
				require.Equal(t, tc.expected, ie)
			} else {
				require.Error(t, err)
			}
		})
	}
}

func TestPDUAddrMarshalBinary(t *testing.T) {
	t.Parallel()

	testCases := []struct {
		name     string
		input    *PDUAddr
		expected []byte
	}{
		{
			name:     "Positive Case - V4",
			expected: []byte{0x01, 0x12, 0x34, 0x56, 0x78},
			input: &PDUAddr{
				IPv4: []byte{0x12, 0x34, 0x56, 0x78},
			},
		},
		{
			name: "Positive Case - V6",
			expected: []byte{
				0x02, 0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			input: &PDUAddr{
				IPv6IfId: []byte{
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name: "Positive Case - V4V6",
			expected: []byte{
				0x03,
				0x12, 0x34, 0x56, 0x78, 0x78, 0x56, 0x34, 0x12,
				0xaa, 0xbb, 0xcc, 0xdd,
			},
			input: &PDUAddr{
				IPv6IfId: []byte{
					0x12, 0x34, 0x56, 0x78, 0x78, 0x56, 0x34, 0x12,
				},
				IPv4: []byte{0xaa, 0xbb, 0xcc, 0xdd},
			},
		},
		{
			name: "Positive Case - V4 + si6lla",
			expected: []byte{
				0x09,
				0x12, 0x34, 0x56, 0x78,
				0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
				0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			input: &PDUAddr{
				IPv4: []byte{0x12, 0x34, 0x56, 0x78},
				SMFIPv6LLA: []byte{
					0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name: "Positive Case - V6 + si6lla",
			expected: []byte{
				0x0a,
				0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
				0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			input: &PDUAddr{
				IPv6IfId: []byte{
					0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				},
				SMFIPv6LLA: []byte{
					0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
		{
			name: "Positive Case - v4V6 + si6lla",
			expected: []byte{
				0x0b,
				0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				0xde, 0xad, 0xbe, 0xef,
				0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
				0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
			},
			input: &PDUAddr{
				IPv6IfId: []byte{
					0xaa, 0xbb, 0xcc, 0xdd, 0x12, 0x34, 0x56, 0x78,
				},
				IPv4: []byte{0xde, 0xad, 0xbe, 0xef},
				SMFIPv6LLA: []byte{
					0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88,
					0x78, 0x56, 0x34, 0x12, 0x12, 0x34, 0x56, 0x78,
				},
			},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := tc.input.MarshalBinary()
			if tc.expected != nil {
				require.NoError(t, err)
				require.Equal(t, tc.expected, b)
			} else {
				require.Error(t, err)
			}
		})
	}
}
